<style>
    .fi-header-heading,.fi-breadcrumbs{display:none!important}.fi-header{margin-bottom:8px!important;min-height:0!important}
    .orion-br-inner,.orion-br-inner *{box-sizing:border-box;font-family:'Cairo',sans-serif}.orion-br-inner{--bi-panel:#0c1728;--bi-border:#21324d;--bi-border-soft:#17263c;--bi-text:#eef3fb;--bi-muted:#71839e;--bi-purple:#8b5cf6;--bi-green:#34d399;--bi-red:#fb7185;--bi-amber:#fbbf24;direction:rtl;color:var(--bi-text);width:100%;padding-bottom:24px}
    .bi-hero{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:116px;padding:17px 19px;margin-bottom:13px;border:1px solid var(--bi-border);border-radius:15px;background:radial-gradient(circle at 8% 10%,rgba(139,92,246,.16),transparent 28%),linear-gradient(145deg,#0e192b,#0a1423);box-shadow:0 18px 45px rgba(0,0,0,.12)}.bi-hero-main{display:flex;align-items:center;gap:13px;min-width:0}.bi-icon{width:48px;height:48px;border-radius:13px;flex:none;display:grid;place-items:center;color:#c3b2ff;border:1px solid rgba(139,92,246,.38);background:linear-gradient(145deg,rgba(124,58,237,.28),rgba(76,29,149,.12));box-shadow:0 10px 25px rgba(76,29,149,.16)}.bi-icon svg{width:22px;height:22px}.bi-eyebrow{color:#8e7be8;font-size:8px;font-weight:950;letter-spacing:1.3px;margin-bottom:4px}.bi-title{color:#f5f7fb;font-size:18px;font-weight:950;line-height:1.25}.bi-sub{color:var(--bi-muted);font-size:9px;font-weight:650;margin-top:5px}.bi-chips{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}.bi-chip{display:inline-flex;align-items:center;gap:6px;min-height:30px;padding:0 10px;border:1px solid #263a58;border-radius:9px;background:#0c1829;color:#9aabc0;font-size:8px;font-weight:900;white-space:nowrap}.bi-chip strong{color:#e4eaf3;font-size:9px;direction:ltr}.bi-chip.green{border-color:rgba(52,211,153,.23);background:rgba(52,211,153,.055);color:#6eddb8}.bi-chip.amber{border-color:rgba(251,191,36,.23);background:rgba(251,191,36,.055);color:#f4ca58}.bi-chip.gray{color:#8290a6}.bi-dot{width:6px;height:6px;border-radius:50%;background:currentColor;box-shadow:0 0 9px currentColor}
    .bi-content .fi-section{overflow:hidden!important;border:1px solid var(--bi-border)!important;border-radius:14px!important;background:linear-gradient(145deg,#0c1728,#091421)!important;box-shadow:none!important}.bi-content .fi-section + .fi-section{margin-top:11px!important}.bi-content .fi-section-header{border-bottom:1px solid var(--bi-border-soft)!important;background:rgba(255,255,255,.012)!important}.bi-content .fi-section-header-heading{color:#e8edf5!important;font-weight:950!important}.bi-content .fi-section-header-description{color:#657792!important;font-size:10px!important}.bi-content .fi-input-wrp,.bi-content .fi-fo-file-upload-input-ctn{border-color:#263a59!important;background:#0d192b!important;box-shadow:none!important}.bi-content .fi-input,.bi-content textarea{color:#e1e8f2!important}.bi-content .fi-fo-field-wrp-label{color:#9aa9bd!important;font-weight:800!important}.bi-content .fi-fo-field-wrp-helper-text{color:#596c87!important}.bi-content .fi-btn-color-primary{box-shadow:0 10px 25px rgba(91,33,182,.18)!important}
